import React, { useState } from 'react';
import './TodoForm.css';

const TodoForm = ({ onAddTodo }) => {
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    status: 'yet_to_start',
    priority: 'medium',
    category: 'general',
    isRecurring: false,
    recurrenceType: 'none',
    tags: [],
  });

  const [tagInput, setTagInput] = useState('');
  const [showForm, setShowForm] = useState(false);

  const priorities = ['low', 'medium', 'high'];
  const statuses = ['yet_to_start', 'in_progress', 'completed'];
  const statusLabels = {
    'yet_to_start': '⭕ Yet to Start',
    'in_progress': '⏳ In Progress',
    'completed': '✅ Completed'
  };
  const categories = ['general', 'work', 'personal', 'shopping', 'health', 'other'];
  const recurrenceTypes = ['none', 'daily', 'weekly', 'monthly'];

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value,
    });
  };

  const handleAddTag = () => {
    if (tagInput.trim() && !formData.tags.includes(tagInput.trim())) {
      setFormData({
        ...formData,
        tags: [...formData.tags, tagInput.trim()],
      });
      setTagInput('');
    }
  };

  const handleRemoveTag = (tag) => {
    setFormData({
      ...formData,
      tags: formData.tags.filter(t => t !== tag),
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.title.trim()) {
      onAddTodo(formData);
      setFormData({
        title: '',
        description: '',
        status: 'yet_to_start',
        priority: 'medium',
        category: 'general',
        isRecurring: false,
        recurrenceType: 'none',
        tags: [],
      });
      setShowForm(false);
    }
  };

  return (
    <div className="todo-form-container">
      {!showForm ? (
        <button
          className="btn-add-todo"
          onClick={() => setShowForm(true)}
        >
          ➕ Add New Todo
        </button>
      ) : (
        <form className="todo-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label htmlFor="title">Task Title *</label>
            <input
              type="text"
              id="title"
              name="title"
              value={formData.title}
              onChange={handleChange}
              placeholder="What needs to be done?"
              required
              autoFocus
              maxLength="100"
            />
          </div>

          <div className="form-group">
            <label htmlFor="description">Description</label>
            <textarea
              id="description"
              name="description"
              value={formData.description}
              onChange={handleChange}
              placeholder="Add more details..."
              rows="3"
              maxLength="500"
            />
          </div>

      <div className="form-row">
        <div className="form-group">
          <label htmlFor="status">Status</label>
          <select
            id="status"
            name="status"
            value={formData.status}
            onChange={handleChange}
          >
            {statuses.map(s => (
              <option key={s} value={s}>{statusLabels[s]}</option>
            ))}
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="priority">Priority</label>
          <select
            id="priority"
            name="priority"
            value={formData.priority}
            onChange={handleChange}
          >
            {priorities.map(p => (
              <option key={p} value={p}>{p.charAt(0).toUpperCase() + p.slice(1)}</option>
            ))}
          </select>
        </div>
      </div>

      <div className="form-row">
        <div className="form-group">
          <label htmlFor="category">Category</label>
          <select
            id="category"
            name="category"
            value={formData.category}
            onChange={handleChange}
          >
            {categories.map(c => (
              <option key={c} value={c}>{c.charAt(0).toUpperCase() + c.slice(1)}</option>
            ))}
          </select>
        </div>
      </div>

          <div className="form-group checkbox">
            <label htmlFor="isRecurring">
              <input
                type="checkbox"
                id="isRecurring"
                name="isRecurring"
                checked={formData.isRecurring}
                onChange={handleChange}
              />
              <span>Make this a recurring task</span>
            </label>
          </div>

          {formData.isRecurring && (
            <div className="form-group">
              <label htmlFor="recurrenceType">Repeat Type</label>
              <select
                id="recurrenceType"
                name="recurrenceType"
                value={formData.recurrenceType}
                onChange={handleChange}
              >
                {recurrenceTypes.map(r => (
                  <option key={r} value={r}>{r.charAt(0).toUpperCase() + r.slice(1)}</option>
                ))}
              </select>
            </div>
          )}

          <div className="form-group">
            <label>Tags</label>
            <div className="tag-input-group">
              <input
                type="text"
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleAddTag()}
                placeholder="Add a tag and press Enter"
              />
              <button type="button" onClick={handleAddTag} className="btn-add-tag">
                Add
              </button>
            </div>
            <div className="tags-list">
              {formData.tags.map(tag => (
                <span key={tag} className="tag">
                  {tag}
                  <button
                    type="button"
                    onClick={() => handleRemoveTag(tag)}
                    className="btn-remove-tag"
                  >
                    ✕
                  </button>
                </span>
              ))}
            </div>
          </div>

          <div className="form-actions">
            <button type="submit" className="btn-submit">✓ Add Todo</button>
            <button
              type="button"
              onClick={() => setShowForm(false)}
              className="btn-cancel"
            >
              ✕ Cancel
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default TodoForm;
